def svg_frenos():
    aria = t("Diagram of checks and balances among the three branches. Congress (legislative), the President (executive), and the courts (judicial) are at the corners of a triangle. The President can veto bills and names judges. Congress can override a veto with two-thirds, impeach the President or judges, and the Senate confirms appointments and treaties. The courts can declare laws and executive actions unconstitutional (judicial review).",
             "Esquema de los controles y equilibrios entre los tres poderes. El Congreso (legislativo), el presidente (ejecutivo) y los tribunales (judicial) están en los vértices de un triángulo. El presidente puede vetar proyectos de ley y nombra a los jueces. El Congreso puede anular un veto con dos tercios, someter a juicio político al presidente o a los jueces, y el Senado confirma nombramientos y tratados. Los tribunales pueden declarar inconstitucionales las leyes y los actos del ejecutivo (revisión judicial).")
    cajas = {"L": (40, 30, t("Congress", "Congreso"), t("legislative · Article I", "legislativo · Artículo I"), "#283593"),
             "E": (460, 30, t("President", "Presidente"), t("executive · Article II", "ejecutivo · Artículo II"), "#9c3d1c"),
             "J": (250, 300, t("Courts", "Tribunales"), t("judicial · Article III", "judicial · Artículo III"), "#2e6b30")}
    s = [f'<svg class="diagrama" style="max-width:720px" viewBox="0 0 720 400" role="img" aria-label="{aria}" xmlns="http://www.w3.org/2000/svg">',
         '<defs><marker id="fl-cb" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10z" fill="#5b6675"/></marker></defs>']
    for k, (x, y, n, sub, c) in cajas.items():
        s.append(f'<rect x="{x}" y="{y}" width="220" height="70" rx="12" fill="{c}"/><text x="{x + 110}" y="{y + 32}" text-anchor="middle" {F} font-size="19" font-weight="700" fill="#fff">{n}</text><text x="{x + 110}" y="{y + 54}" text-anchor="middle" {F} font-size="13" fill="#fff">{sub}</text>')
    fl = [((460, 52), (262, 52), [t("veto", "veto")], (361, 44), "middle"),
          ((262, 78), (460, 78), [t("override veto · impeach · confirm", "anular veto · juicio político · confirmar")], (361, 124), "middle"),
          ((560, 100), (430, 300), [t("names", "nombra"), t("judges", "jueces")], (512, 196), "start"),
          ((380, 300), (510, 100), [t("rules acts", "declara actos"), t("unconstitutional", "inconstitucionales")], (450, 176), "end"),
          ((150, 100), (270, 300), [t("impeach ·", "juicio político ·"), t("confirm judges", "confirma jueces")], (196, 196), "end"),
          ((310, 300), (190, 100), [t("judicial", "revisión"), t("review", "judicial")], (250, 176), "start")]
    for (a, b, txt, (tx, ty), anc) in fl:
        s.append(f'<line x1="{a[0]}" y1="{a[1]}" x2="{b[0]}" y2="{b[1]}" stroke="#5b6675" stroke-width="2.5" marker-end="url(#fl-cb)"/>')
        for i, l in enumerate(txt):
            s.append(f'<text x="{tx}" y="{ty + i * 17}" text-anchor="{anc}" {F} font-size="13" font-weight="700" fill="#1a2330" paint-order="stroke" stroke="#fbfaf7" stroke-width="5">{l}</text>')
    s.append("</svg>")
    return "".join(s)


