# ---------------------------------------------------------------- la práctica
def banco_articulo():
    A = ["I", "II", "III", "V", "VI", "VII"]
    ops = [t("Article", "Artículo") + " " + a for a in A]
    datos = [
        (t("Congress decides whether to declare war.", "El Congreso decide si declara la guerra."), 0), (t("How the President is chosen and what powers the office has.", "Cómo se elige al presidente y qué poderes tiene el cargo."), 1),
        (t("The Supreme Court and the lower federal courts.", "El Tribunal Supremo y los tribunales federales inferiores."), 2), (t("Proposing a new amendment needs two-thirds of both houses of Congress.", "Proponer una enmienda nueva requiere dos tercios de las dos cámaras del Congreso."), 3),
        (t("A valid federal law wins over a state law that contradicts it.", "Una ley federal válida prevalece sobre una ley estatal que la contradiga."), 4), (t("Nine states were enough to put the Constitution into effect.", "Bastaban nueve estados para que la Constitución entrara en vigor."), 5),
        (t("How a bill becomes a law, and the President’s veto.", "Cómo un proyecto se convierte en ley, y el veto del presidente."), 0), (t("The President is commander in chief of the armed forces.", "El presidente es el comandante en jefe de las fuerzas armadas."), 1),
        (t("Federal judges hold their offices “during good behaviour.”", "Los jueces federales conservan sus cargos «mientras observen buena conducta»."), 2), (t("Officials swear an oath to support the Constitution.", "Los cargos públicos juran apoyar la Constitución."), 4),
    ]
    return [{"enun": t("Which article covers this?", "¿Qué artículo regula esto?") + "<br><strong>" + s + "</strong>", "ops": ops, "ok": k, "exp": f"<strong>{ops[k]}.</strong>", "enOrden": True} for s, k in datos]


def banco_principio():
    P5 = [t("Popular sovereignty", "Soberanía popular"), t("Limited government", "Gobierno limitado"), t("Separation of powers", "Separación de poderes"), t("Checks and balances", "Controles y equilibrios"), t("Federalism", "Federalismo")]
    datos = [
        (t("Voters elect their representatives every two years.", "Los votantes eligen a sus representantes cada dos años."), 0),
        (t("A court rules that a law goes beyond what the Constitution allows Congress to do.", "Un tribunal decide que una ley va más allá de lo que la Constitución permite al Congreso."), 1),
        (t("Congress makes the laws, the President carries them out, and the courts interpret them.", "El Congreso hace las leyes, el presidente las ejecuta y los tribunales las interpretan."), 2),
        (t("The House impeaches a federal judge.", "La Cámara somete a juicio político a un juez federal."), 3),
        (t("Illinois sets its own rules for getting a driver’s license.", "Illinois fija sus propias reglas para obtener la licencia de conducir."), 4),
        (t("The Senate rejects a treaty the President signed.", "El Senado rechaza un tratado que firmó el presidente."), 3),
        (t("The Constitution begins with “We the People.”", "La Constitución empieza con «We the People»."), 0),
        (t("Both the national government and the states collect taxes.", "Tanto el gobierno nacional como los estados cobran impuestos."), 4),
        (t("The Bill of Rights lists things the government may not do.", "La Carta de Derechos enumera cosas que el gobierno no puede hacer."), 1),
        (t("No person can be a member of Congress and a federal judge at the same time.", "Ninguna persona puede ser a la vez miembro del Congreso y juez federal."), 2),
    ]
    return [{"enun": t("Which principle is at work?", "¿Qué principio actúa?") + "<br><strong>" + s + "</strong>", "ops": P5, "ok": k, "exp": f"<strong>{P5[k]}.</strong>", "enOrden": True} for s, k in datos]


def casos_debate():
    G = [t("Federalist", "Federalista"), t("Anti-Federalist", "Antifederalista")]
    PF = t("Does it fear weakness and disorder, or defend a strong Union?", "¿Teme la debilidad y el desorden, o defiende una Unión fuerte?")
    PA = t("Does it fear a distant, too-powerful government, or defend the states and rights?", "¿Teme un gobierno lejano y demasiado poderoso, o defiende a los estados y los derechos?")
    def caso(tit, piezas):
        return {"titulo": tit, "intro": t("Who would have written each sentence?", "¿Quién habría escrito cada frase?"), "grupos": G, "etiqueta": t("Written by a…", "Lo escribió un…"),
                "piezas": [{"t": a, "v": v, "pista": [PF, PA][v]} for a, v in piezas]}
    return [
        caso(t("Set 1", "Serie 1"), [(t("“Under the Articles of Confederation, Congress could not even pay the army.”", "«Con los Artículos de la Confederación, el Congreso ni siquiera podía pagar al ejército»."), 0),
                                      (t("“A government so far away cannot know the needs of the farmers of my county.”", "«Un gobierno tan lejano no puede conocer las necesidades de los agricultores de mi condado»."), 1),
                                      (t("“In a large republic, many interests check each other, and no faction can rule.”", "«En una república grande, muchos intereses se frenan entre sí, y ninguna facción puede mandar»."), 0),
                                      (t("“Where is the guarantee of a free press and trial by jury? I see none in this document.”", "«¿Dónde está la garantía de la libertad de prensa y del juicio por jurado? No veo ninguna en este documento»."), 1)]),
        caso(t("Set 2", "Serie 2"), [(t("“The states quarrel over trade and borders; only a stronger Union can settle it.”", "«Los estados se pelean por el comercio y las fronteras; solo una Unión más fuerte puede resolverlo»."), 0),
                                      (t("“The ‘necessary and proper’ clause lets Congress decide for itself how far its power reaches.”", "«La cláusula de lo ‘necesario y conveniente’ deja que el Congreso decida por sí mismo hasta dónde llega su poder»."), 1),
                                      (t("“Ambition must be made to counteract ambition.”", "«La ambición debe ponerse a contrarrestar a la ambición»."), 0),
                                      (t("“The states will become mere shadows, and all power will flow to the capital.”", "«Los estados quedarán reducidos a sombras, y todo el poder irá a parar a la capital»."), 1)]),
    ]


def practica():
    A = {"en": ["structure", "principles", "debate"], "es": ["estructura", "principios", "debate"]}[C.L]
    mods = [
        (A[0], t("Where is it in the Constitution?", "¿Dónde está en la Constitución?"), C.om("m1", t("Remember: I makes the laws, II carries them out, III judges them; V amends; VI is supremacy; VII is ratification.", "Recuerde: el I hace las leyes, el II las ejecuta, el III las juzga; el V enmienda; el VI es la supremacía; el VII, la ratificación."))),
        (A[1], t("Which principle?", "¿Qué principio?"), C.om("m2", t("Ask: is it about where authority comes from, what government may not do, who does which job, one branch stopping another, or the states and the Union?", "Pregúntese: ¿trata de dónde viene la autoridad, de lo que el gobierno no puede hacer, de quién hace cada trabajo, de un poder que frena a otro, o de los estados y la Unión?"))),
        (A[2], t("Federalist or Anti-Federalist?", "¿Federalista o antifederalista?"), C.clasifica("m3", t("Read each sentence and decide which side would have written it. If something is not right, the sentences marked in yellow get a hint.", "Lea cada frase y decida qué bando la habría escrito. Si algo no está bien, las frases marcadas en amarillo reciben una pista."))),
    ]
    js = C.js_datos("ART", banco_articulo()) + C.js_datos("PRI", banco_principio()) + C.js_datos("DEB", casos_debate()) + 'creaBanco("m1", ART);\ncreaBanco("m2", PRI);\ncreaClasifica("m3", DEB);\n'
    return C.pagina_practica(N, titulo(), t("Three activities · the order of the exercises changes every time · two tries in each one", "Tres actividades · el orden de los ejercicios cambia cada vez · dos intentos en cada uno"), mods, js)


if __name__ == "__main__":
    C.construye(N, leccion, practica)
